def can_form_palindrome_by_split(a, b):
 def check(left,right):
  i,j=0,len(left)-1
  while i<j and left[i]==right[j]:i+=1;j-=1
  return i>=j or left[i:j+1]==left[i:j+1][::-1] or right[i:j+1]==right[i:j+1][::-1]
 return check(a,b) or check(b,a)

